  "correct": 5,
  "explanation": "Shortcut: only A is affected. Y in A next year = 750 × 1.2 = 900; B is unchanged, so Y in B = 450. Numerator = 1350. Denominator (current year) = X in C + X in D = 540 + 1500 = 2040. 1350 / 2040 × 100 ≈ 66.2%.",
