  "question": "In a new city F, the sales of product X are 20% of the sales of product X in city E, and the sales of product Y are two-thirds of the sales of product Y in city A. If F is also considered, the total sales of product Y in all six cities together is what percent less than the total sales of product X in all six cities together?",
