  "question": "Which of the following statements is/are true? I. The number of defective items in plant S is 25% more than the number of defective items in plant Q. II. The ratio of the non-defective items in plant P to the defective items in plant T is 17 : 5. III. The difference between the number of items produced by plant T and the non-defective items in plant Q is 196.",
