  "question": "The average of number of items sold by the company on first 4 days of the week is 375. The average of the item sold on first four days of week exceeds the average items sold on last four days of week by 32.5. If the sales on day four is 370, then find the average number of items sold in the whole week (approx. to two decimal places).",
