  "question": "A person invests Rs. K for 2 years at a simple interest rate of 10%. The total sum of money that the individual receives is divided in the ratio of 5:4. They then reinvest the first part for 2 years at a compound interest rate of 20%, and the other part for three years at a simple interest rate of 30%. What is the value of K if the total interest earned by the person from the two parts is Rs.9280?",
