  "question": "A sum of P Rs. is amounted to 156800 Rs. in 2 years at 12% per annum compounded annually. If the same sum is invested into compound interest at 8% per annum for 2 years and (P + 5000) Rs. is invested into simple interest at 12% rate of interest for the same time period then what is the total interest earned?",
