  "question": "A invested Rs. X and B invested Rs. (X + 900) in a business for 12 months and 8 months respectively. If the total profit earned at the end of the year is Rs. 5800 and the profit share of B is Rs. 1000 more than the profit share of A, then find the amount invested by B in the business.",
