  "question": "Two trains when moving in the same direction take 350 sec to cross each other and take 10 seconds to cross each other while moving in the opposite direction. The speed of the faster train is 18 m/s. If the total length of the trains(both A and B together) is is D then what is the value of 2D+12?",
