  "question": "A’, ‘B’ and ‘C’ started a business by investing Rs. 2500, Rs. 4500 and Rs. 3500, respectively. After 4 months, ‘B’ left and ‘A’ and ‘C’ added Rs. 1000 each to their respective initial investment. Find the ratio of annual profit received by ‘A’, ‘B’ and ‘C’.",
